-- =====================================================================
-- e-MART seed data v3  —  Flipkart-style catalogue
--
--   77 categories  (20 top-level -> sub-categories)
--   252 products   with brand / stock / rating / discount
--   1271 images     4-6 per product, EVERY image matched to its product
--   10 users     5 approved cardholders, 1 pending, 1 rejected, 1 deactivated
--
-- IMAGES: served from frontend/public/images/products/*.svg — real files in
-- the repo, so they need no internet, no CDN and no CORS. The filename carries
-- the product name, and each image renders that product's name, brand and a
-- category-appropriate icon. Swap in photographs by overwriting the files or
-- updating image_url; nothing in the code assumes SVG.
--
-- Every password is: Password@123
-- Run AFTER emart_schema.sql.
-- =====================================================================

USE emart;

-- ------------------------------------------------- clear ALL existing data
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE payment;         TRUNCATE TABLE order_details;
TRUNCATE TABLE orders;          TRUNCATE TABLE wishlist;
TRUNCATE TABLE cart_items;      TRUNCATE TABLE cart;
TRUNCATE TABLE product_image;   TRUNCATE TABLE prod_dtl_master;
TRUNCATE TABLE config_master;   TRUNCATE TABLE product_master;
TRUNCATE TABLE category_master; TRUNCATE TABLE emart_card;
TRUNCATE TABLE address;         TRUNCATE TABLE users;
SET FOREIGN_KEY_CHECKS = 1;

