-- --------------------------------------------------- AUTO_INCREMENT reset
ALTER TABLE users           AUTO_INCREMENT = 100;
ALTER TABLE address         AUTO_INCREMENT = 100;
ALTER TABLE emart_card      AUTO_INCREMENT = 100;
ALTER TABLE category_master AUTO_INCREMENT = 500;
ALTER TABLE product_master  AUTO_INCREMENT = 1000;
ALTER TABLE product_image   AUTO_INCREMENT = 5000;
ALTER TABLE config_master   AUTO_INCREMENT = 100;
ALTER TABLE prod_dtl_master AUTO_INCREMENT = 500;
ALTER TABLE cart            AUTO_INCREMENT = 100;
ALTER TABLE cart_items      AUTO_INCREMENT = 100;
ALTER TABLE wishlist        AUTO_INCREMENT = 100;
ALTER TABLE orders          AUTO_INCREMENT = 100;
ALTER TABLE order_details   AUTO_INCREMENT = 100;
ALTER TABLE payment         AUTO_INCREMENT = 100;

-- ------------------------------------------------------------ quick check
SELECT (SELECT COUNT(*) FROM category_master) AS categories,
       (SELECT COUNT(*) FROM product_master)  AS products,
       (SELECT COUNT(*) FROM product_image)   AS images,
       (SELECT COUNT(*) FROM users)           AS users,
       (SELECT COUNT(*) FROM emart_card WHERE status='APPROVED') AS approved_cards;